insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002011', 'I am writing to', '/aɪ æm ˈraɪtɪŋ tuː/', 'phrase', 'estou escrevendo para', 'I am writing to inquire about the position.', 'Estou escrevendo para perguntar sobre a vaga.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002012', 'follow up on', '/ˈfɑːloʊ ʌp ɒn/', 'phrase', 'dar continuidade a', 'I wanted to follow up on my previous email.', 'Eu queria dar continuidade ao meu e-mail anterior.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002013', 'please find attached', '/pliːz faɪnd əˈtætʃt/', 'phrase', 'segue em anexo', 'Please find attached the report you requested.', 'Segue em anexo o relatório que você solicitou.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002014', 'I would appreciate it if', '/aɪ wʊd əˈpriːʃieɪt ɪt ɪf/', 'phrase', 'eu agradeceria se', 'I would appreciate it if you could confirm by Friday.', 'Eu agradeceria se você pudesse confirmar até sexta-feira.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002015', 'at your earliest convenience', '/æt jɔːr ˈɜːrliəst kənˈviːniəns/', 'phrase', 'assim que possível', 'Please reply at your earliest convenience.', 'Por favor, responda assim que possível.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002016', 'kindly', '/ˈkaɪndli/', 'adverb', 'gentilmente', 'Kindly review the attached document.', 'Por gentileza, revise o documento anexo.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002017', 'regarding', '/rɪˈɡɑːrdɪŋ/', 'preposition', 'com relação a', 'I am writing regarding your recent request.', 'Estou escrevendo com relação à sua solicitação recente.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002018', 'with reference to', '/wɪð ˈrefərəns tuː/', 'phrase', 'com referência a', 'With reference to our phone call, please find the details below.', 'Com referência à nossa ligação, seguem os detalhes abaixo.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002019', 'I look forward to', '/aɪ lʊk ˈfɔːrwərd tuː/', 'phrase', 'aguardo ansiosamente', 'I look forward to hearing from you soon.', 'Aguardo ansiosamente sua resposta em breve.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002020', 'please do not hesitate to', '/pliːz duː nɑːt ˈhezɪteɪt tuː/', 'phrase', 'não hesite em', 'Please do not hesitate to contact me if you need anything.', 'Não hesite em me contatar se precisar de algo.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002021', 'should you have any questions', '/ʃʊd juː hæv ˈeni ˈkwestʃənz/', 'phrase', 'caso tenha alguma dúvida', 'Should you have any questions, feel free to reach out.', 'Caso tenha alguma dúvida, sinta-se à vontade para entrar em contato.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002022', 'I apologize for the inconvenience', '/aɪ əˈpɑːlədʒaɪz fɔːr ði ɪnkənˈviːniəns/', 'phrase', 'peço desculpas pelo transtorno', 'I apologize for the inconvenience this may have caused.', 'Peço desculpas pelo transtorno que isso possa ter causado.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002023', 'as per our conversation', '/æz pɜːr aʊər ˌkɑːnvərˈseɪʃən/', 'phrase', 'conforme nossa conversa', 'As per our conversation, I am sending the updated proposal.', 'Conforme nossa conversa, estou enviando a proposta atualizada.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002024', 'enclosed', '/ɪnˈkloʊzd/', 'adjective', 'anexo/incluso', 'Please review the enclosed documents.', 'Por favor, revise os documentos anexos.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002025', 'correspondence', '/ˌkɔːrəˈspɑːndəns/', 'noun', 'correspondência', 'All correspondence should be sent to this address.', 'Toda correspondência deve ser enviada para este endereço.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002026', 'recipient', '/rɪˈsɪpiənt/', 'noun', 'destinatário', 'Make sure the recipient''s name is spelled correctly.', 'Certifique-se de que o nome do destinatário está escrito corretamente.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002027', 'cc', '/siː siː/', 'noun', 'cópia (e-mail)', 'Please cc my manager on this email.', 'Por favor, coloque meu gerente em cópia neste e-mail.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002028', 'subject line', '/ˈsʌbdʒɪkt laɪn/', 'noun', 'assunto do e-mail', 'Keep the subject line short and clear.', 'Mantenha o assunto do e-mail curto e claro.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002029', 'formal tone', '/ˈfɔːrməl toʊn/', 'noun', 'tom formal', 'Business emails usually require a formal tone.', 'E-mails de negócios geralmente exigem um tom formal.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002030', 'proofread', '/ˈpruːfriːd/', 'verb', 'revisar', 'Always proofread your email before sending it.', 'Sempre revise seu e-mail antes de enviá-lo.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002031', 'sincerely', '/sɪnˈsɪrli/', 'adverb', 'atenciosamente', 'The email ended with "Sincerely, John Smith".', 'O e-mail terminou com "Atenciosamente, John Smith".', 'B2', array['email']),
('30000000-0000-0000-0000-000000002032', 'best regards', '/best rɪˈɡɑːrdz/', 'phrase', 'atenciosamente', 'She closed the message with "Best regards".', 'Ela encerrou a mensagem com "Atenciosamente".', 'B2', array['email']),
('30000000-0000-0000-0000-000000002033', 'to whom it may concern', '/tuː huːm ɪt meɪ kənˈsɜːrn/', 'phrase', 'a quem possa interessar', 'Use "To whom it may concern" when you do not know the recipient''s name.', 'Use "To whom it may concern" quando você não sabe o nome do destinatário.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002034', 'cordial', '/ˈkɔːrdʒəl/', 'adjective', 'cordial', 'Keep the tone cordial, even when the topic is difficult.', 'Mantenha o tom cordial, mesmo quando o assunto é difícil.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002035', 'reschedule', '/riːˈskedʒuːl/', 'verb', 'reagendar', 'I need to reschedule our meeting to next week.', 'Preciso reagendar nossa reunião para a próxima semana.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002036', 'confirm receipt', '/kənˈfɜːrm rɪˈsiːt/', 'phrase', 'confirmar recebimento', 'Please confirm receipt of this email.', 'Por favor, confirme o recebimento deste e-mail.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002037', 'attach', '/əˈtætʃ/', 'verb', 'anexar', 'Remember to attach the invoice before sending.', 'Lembre-se de anexar a fatura antes de enviar.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002038', 'forward', '/ˈfɔːrwərd/', 'verb', 'encaminhar', 'Could you forward this message to the team?', 'Você poderia encaminhar esta mensagem para a equipe?', 'B2', array['email']),
('30000000-0000-0000-0000-000000002039', 'respond promptly', '/rɪˈspɑːnd ˈprɑːmptli/', 'phrase', 'responder prontamente', 'We try to respond promptly to all customer emails.', 'Tentamos responder prontamente a todos os e-mails de clientes.', 'B2', array['email']),
('30000000-0000-0000-0000-000000002040', 'professional courtesy', '/prəˈfeʃənəl ˈkɜːrtəsi/', 'noun', 'cortesia profissional', 'Replying to every email is a matter of professional courtesy.', 'Responder a todo e-mail é uma questão de cortesia profissional.', 'B2', array['email']);

