-- Lição 336: Aberturas formais de e-mail (I am writing to, follow up on, please find attached, I would appreciate it if, at your earliest convenience, kindly)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000336', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002011", "show_image": false}'),
('20000000-0000-0000-0000-000000000336', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002013", "show_image": false}'),
('20000000-0000-0000-0000-000000000336', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002015", "show_image": false}'),
('20000000-0000-0000-0000-000000000336', 'multiple_choice', 4, '{"question": "___ inquire about the position.", "audio_text": null, "options": ["I am writing to", "Please find attached", "Kindly"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000336', 'multiple_choice', 5, '{"question": "I wanted to ___ my previous email.", "audio_text": null, "options": ["follow up on", "attach", "reschedule"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000336', 'matching', 6, '{"pairs": [{"left": "I am writing to", "right": "estou escrevendo para"}, {"left": "follow up on", "right": "dar continuidade a"}, {"left": "please find attached", "right": "segue em anexo"}, {"left": "I would appreciate it if", "right": "eu agradeceria se"}, {"left": "at your earliest convenience", "right": "assim que possível"}, {"left": "kindly", "right": "gentilmente"}]}'),
('20000000-0000-0000-0000-000000000336', 'fill_blank', 7, '{"sentence": "___ the report you requested.", "options": ["Please find attached", "I am writing to", "Kindly"], "correct": "Please find attached", "translation": "Segue em anexo o relatório que você solicitou."}'),
('20000000-0000-0000-0000-000000000336', 'fill_blank', 8, '{"sentence": "___ review the attached document.", "options": ["Kindly", "Regarding", "Enclosed"], "correct": "Kindly", "translation": "Por gentileza, revise o documento anexo."}'),
('20000000-0000-0000-0000-000000000336', 'word_order', 9, '{"words": ["I", "would", "appreciate", "it", "if", "you", "could", "confirm", "by", "Friday"], "correct_sentence": "I would appreciate it if you could confirm by Friday", "translation": "Eu agradeceria se você pudesse confirmar até sexta-feira"}'),
('20000000-0000-0000-0000-000000000336', 'word_order', 10, '{"words": ["Please", "reply", "at", "your", "earliest", "convenience"], "correct_sentence": "Please reply at your earliest convenience", "translation": "Por favor, responda assim que possível"}'),
('20000000-0000-0000-0000-000000000336', 'reading', 11, '{"passage": "Formal emails often open with a clear purpose. Phrases like \"I am writing to\" explain why you are contacting someone, while \"I wanted to follow up on\" reminds the reader of a previous message. When sending a document, \"please find attached\" is standard, and \"I would appreciate it if\" softens a request politely.", "translation": "E-mails formais geralmente começam com um propósito claro. Frases como \"I am writing to\" explicam por que você está entrando em contato, enquanto \"I wanted to follow up on\" lembra o leitor de uma mensagem anterior. Ao enviar um documento, \"please find attached\" é padrão, e \"I would appreciate it if\" suaviza um pedido educadamente.", "question": "What does \"I wanted to follow up on\" do, according to the text?", "options": ["Explains why you are writing", "Reminds the reader of a previous message", "Attaches a document"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000336', 'listening', 12, '{"audio_text": "I am writing to inquire about the position. I wanted to follow up on my previous email. Please find attached the report you requested.", "question": "What is attached, according to the audio?", "options": ["A proposal", "The report", "An invoice"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000336', 'dictation', 13, '{"audio_text": "I am writing to inquire about the position.", "expected": "I am writing to inquire about the position."}'),
('20000000-0000-0000-0000-000000000336', 'typing', 14, '{"prompt_pt": "Traduza (e-mail formal): ''Estou escrevendo para dar continuidade à nossa conversa da semana passada.''", "expected": "I am writing to follow up on our conversation from last week.", "ai_review": true}'),

