('20000000-0000-0000-0000-000000000337', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002017", "show_image": false}'),
('20000000-0000-0000-0000-000000000337', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002019", "show_image": false}'),
