('20000000-0000-0000-0000-000000000337', 'multiple_choice', 4, '{"question": "I am writing ___ your recent request.", "audio_text": null, "options": ["regarding", "attach", "cordial"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000337', 'multiple_choice', 5, '{"question": "I ___ hearing from you soon.", "audio_text": null, "options": ["look forward to", "am writing to", "would appreciate"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000337', 'matching', 6, '{"pairs": [{"left": "regarding", "right": "com relação a"}, {"left": "with reference to", "right": "com referência a"}, {"left": "I look forward to", "right": "aguardo ansiosamente"}, {"left": "please do not hesitate to", "right": "não hesite em"}, {"left": "should you have any questions", "right": "caso tenha alguma dúvida"}, {"left": "I apologize for the inconvenience", "right": "peço desculpas pelo transtorno"}]}'),
('20000000-0000-0000-0000-000000000337', 'fill_blank', 7, '{"sentence": "Please do not hesitate ___ contact me if you need anything.", "options": ["to", "for", "with"], "correct": "to", "translation": "Não hesite em me contatar se precisar de algo."}'),
('20000000-0000-0000-0000-000000000337', 'fill_blank', 8, '{"sentence": "___ our phone call, please find the details below.", "options": ["With reference to", "I look forward to", "Regarding"], "correct": "With reference to", "translation": "Com referência à nossa ligação, seguem os detalhes abaixo."}'),
('20000000-0000-0000-0000-000000000337', 'word_order', 9, '{"words": ["Should", "you", "have", "any", "questions", "feel", "free", "to", "reach", "out"], "correct_sentence": "Should you have any questions feel free to reach out", "translation": "Caso tenha alguma dúvida, sinta-se à vontade para entrar em contato"}'),
('20000000-0000-0000-0000-000000000337', 'word_order', 10, '{"words": ["I", "apologize", "for", "the", "inconvenience", "this", "may", "have", "caused"], "correct_sentence": "I apologize for the inconvenience this may have caused", "translation": "Peço desculpas pelo transtorno que isso possa ter causado"}'),
('20000000-0000-0000-0000-000000000337', 'reading', 11, '{"passage": "Professional emails often connect back to previous conversations. \"Regarding\" and \"with reference to\" both point to a topic already discussed. Closing lines like \"I look forward to hearing from you\" and \"please do not hesitate to contact me\" invite a reply, while \"should you have any questions\" and an apology for inconvenience show politeness and care.", "translation": "E-mails profissionais costumam se conectar a conversas anteriores. \"Regarding\" e \"with reference to\" ambos apontam para um assunto já discutido. Linhas de fechamento como \"I look forward to hearing from you\" e \"please do not hesitate to contact me\" convidam a uma resposta, enquanto \"should you have any questions\" e um pedido de desculpas pelo transtorno mostram educação e cuidado.", "question": "What do \"regarding\" and \"with reference to\" both do, according to the text?", "options": ["Apologize for a mistake", "Point to a topic already discussed", "Invite a reply"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000337', 'listening', 12, '{"audio_text": "I am writing regarding your recent request. I look forward to hearing from you soon. Please do not hesitate to contact me if you need anything.", "question": "What is the writer looking forward to, according to the audio?", "options": ["A meeting", "Hearing from the reader soon", "An invoice"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000337', 'dictation', 13, '{"audio_text": "I look forward to hearing from you soon.", "expected": "I look forward to hearing from you soon."}'),
('20000000-0000-0000-0000-000000000337', 'typing', 14, '{"prompt_pt": "Traduza (e-mail formal): ''Caso tenha alguma dúvida, não hesite em me contatar.''", "expected": "Should you have any questions, please do not hesitate to contact me.", "ai_review": true}'),

