('20000000-0000-0000-0000-000000000338', 'multiple_choice', 5, '{"question": "Keep the ___ short and clear.", "audio_text": null, "options": ["subject line", "recipient", "correspondence"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000338', 'matching', 6, '{"pairs": [{"left": "as per our conversation", "right": "conforme nossa conversa"}, {"left": "enclosed", "right": "anexo/incluso"}, {"left": "correspondence", "right": "correspondência"}, {"left": "recipient", "right": "destinatário"}, {"left": "cc", "right": "cópia (e-mail)"}, {"left": "subject line", "right": "assunto do e-mail"}]}'),
('20000000-0000-0000-0000-000000000338', 'fill_blank', 7, '{"sentence": "Make sure the ___''s name is spelled correctly.", "options": ["recipient", "correspondence", "subject line"], "correct": "recipient", "translation": "Certifique-se de que o nome do destinatário está escrito corretamente."}'),
('20000000-0000-0000-0000-000000000338', 'fill_blank', 8, '{"sentence": "Please ___ my manager on this email.", "options": ["cc", "attach", "forward"], "correct": "cc", "translation": "Por favor, coloque meu gerente em cópia neste e-mail."}'),
('20000000-0000-0000-0000-000000000338', 'word_order', 9, '{"words": ["As", "per", "our", "conversation", "I", "am", "sending", "the", "updated", "proposal"], "correct_sentence": "As per our conversation I am sending the updated proposal", "translation": "Conforme nossa conversa, estou enviando a proposta atualizada"}'),
('20000000-0000-0000-0000-000000000338', 'word_order', 10, '{"words": ["All", "correspondence", "should", "be", "sent", "to", "this", "address"], "correct_sentence": "All correspondence should be sent to this address", "translation": "Toda correspondência deve ser enviada para este endereço"}'),
('20000000-0000-0000-0000-000000000338', 'reading', 11, '{"passage": "Good email etiquette relies on precise vocabulary. \"As per our conversation\" refers back to something already discussed, and \"enclosed\" describes documents included with the message. It is important to check that the recipient''s address is correct, decide who to cc, keep all correspondence organized, and write a clear subject line.", "translation": "Uma boa etiqueta de e-mail depende de vocabulário preciso. \"As per our conversation\" se refere a algo já discutido, e \"enclosed\" descreve documentos incluídos na mensagem. É importante verificar se o endereço do destinatário está correto, decidir quem colocar em cópia, manter toda a correspondência organizada e escrever um assunto claro.", "question": "What does \"enclosed\" describe, according to the text?", "options": ["The subject line", "Documents included with the message", "The recipient''s address"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000338', 'listening', 12, '{"audio_text": "As per our conversation, I am sending the updated proposal. Please review the enclosed documents. Keep the subject line short and clear.", "question": "What is the writer sending, according to the audio?", "options": ["An invoice", "The updated proposal", "A contract"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000338', 'dictation', 13, '{"audio_text": "Please review the enclosed documents.", "expected": "Please review the enclosed documents."}'),
('20000000-0000-0000-0000-000000000338', 'typing', 14, '{"prompt_pt": "Traduza (e-mail formal): ''Conforme nossa conversa, o destinatário já foi adicionado em cópia.''", "expected": "As per our conversation, the recipient has already been added in cc.", "ai_review": true}'),

